import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';
import UnoCSS from 'unocss/vite';

/**
 * Development uses portless (`portless issue-2-web pnpm run dev`), which injects
 * HOST/PORT. The backend is reached same-origin in production; in development
 * Vite proxies `/api` to the portless-exposed backend
 * (`VITE_DEV_API_TARGET`, default http://127.0.0.1:3001).
 */
const host = process.env.HOST?.trim() || 'localhost';
const port = process.env.PORT ? Number.parseInt(process.env.PORT, 10) : 5173;
const apiTarget = process.env.VITE_DEV_API_TARGET?.trim() || 'http://127.0.0.1:3001';

export default defineConfig({
  plugins: [react(), UnoCSS()],
  server: {
    host,
    port,
    strictPort: Boolean(process.env.PORT),
    allowedHosts: ['.localhost', 'localhost', '127.0.0.1'],
    proxy: {
      '/api': { target: apiTarget, changeOrigin: true },
    },
  },
  build: {
    outDir: 'dist',
    emptyOutDir: true,
  },
});
