import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import { BrowserRouter } from 'react-router-dom';
import 'virtual:uno.css';
import './styles.css';
import { App } from './App';

const container = document.getElementById('root');
if (!container) throw new Error('Root container #root is missing from index.html');

createRoot(container).render(
  <StrictMode>
    <BrowserRouter>
      <App />
    </BrowserRouter>
  </StrictMode>,
);

/**
 * A1-range parsing, serialisation and the single structural shift helper
 * consumed by validation rules, filters and pivot source ranges.
 *
 * The same coordinate-mapping layer is reused by the formula-reference rewrite
 * that sub-issue C owns; this module only implements the range-level view
 * because that is what B persists. See Issue #4 comment #35 (D-B3):
 *
 * - Insert at the new block's first index `p`, `count` slots: `p <= r1` shifts
 *   the whole range down; `r1 < p <= r2` expands the range by `count`
 *   (an insertion inside a region stays inside it); `p > r2` changes nothing.
 * - Delete at `d`: `d < r1` shifts the whole range up; `r1 <= d <= r2`
 *   shrinks the range by one with `r1` fixed (`r2 -= 1`, so data that was below
 *   the deleted slot stays covered); a range that collapses (`r1 > r2`,
 *   i.e. exactly the deleted single row/column) is removed.
 *
 * Parsing is deliberately lenient: any expression this module cannot parse is
 * returned unchanged (`changed: false`) so an unknown stored format is never
 * corrupted by a structure operation.
 */

/** @typedef {{ r1: number, c1: number, r2: number, c2: number }} Rect */
/** @typedef {{ range: string, changed: boolean }} ShiftResult */
/** @typedef {'row' | 'column'} Axis */

const A1_RANGE = /^\$?([A-Za-z]+)\$?([1-9][0-9]*)(?::\$?([A-Za-z]+)\$?([1-9][0-9]*))?$/;

/**
 * Column index (0-based) to spreadsheet letters: 0 -> "A", 25 -> "Z", 26 -> "AA".
 *
 * @param {number} col
 * @returns {string}
 */
export function columnLabel(col) {
  let value = col + 1;
  let label = '';
  while (value > 0) {
    const remainder = (value - 1) % 26;
    label = String.fromCharCode(65 + remainder) + label;
    value = Math.floor((value - 1) / 26);
  }
  return label;
}

